  // accord au singulier quand la quantité vaut 1 (« 1 agent », « 1 policier municipal »)
  const SING = { municipaux: 'municipal', lieux: 'lieu', nouveaux: 'nouveau', communaux: 'communal', sociaux: 'social', bureaux: 'bureau' };
  function sing(t) { return t.replace(/(^|[^\d,])1 ((?:[a-zéèêàâîôûç’'-]+ ?){1,3})/i, (m, a, w) => a + '1 ' + w.split(' ').map((x, i) => i > 1 ? x : SING[x] || (/[^s]s$/.test(x) && x.length > 3 ? x.slice(0, -1) : x)).join(' ')); }
  // Qui décide ? compétences réelles de chaque mesure
  const CP = { mercosur: ['ue', 'etat'], thermique: ['ue', 'etat'], defeur: ['ue', 'etat'], contrib: ['etat', 'ue'], achatfr: ['ue'], ukraine: ['etat', 'ue'], medreg: ['etat'], rail: ['etat'], normes: ['etat', 'ue'], prixagri: ['etat', 'ue'] };
  LEVERS.forEach(l => { l.cp = l.cp || CP[l.id] || (l.lvl === 'local' ? ['com'] : ['etat']); });
  const CP_L = { com: 'la commune', dep: 'le Département', reg: 'la Région', etat: 'l’État (Parlement et gouvernement)', ue: 'l’Union européenne', sen: 'le Parlement' };
  const TYPE_CP = { mun: 'com', dep: 'dep', reg: 'reg', sen: 'sen', leg: 'etat', pres: 'etat', euro: 'ue' };
  const CAT_CP = { l_transco: ['com', 'reg'], l_sante: ['com', 'dep'] };
  function cpOf(m) { if (!m) return null; if (m.cp) return m.cp; const lev = m.lever && LEVERS.find(z => z.id === m.lever); if (lev) return lev.cp; if (m.src && CAT_CP[m.src]) return CAT_CP[m.src]; return (m.level || m.lvl) === 'national' ? ['etat'] : ['com']; }
  function inComp(m, t) { const c = TYPE_CP[t]; if (!c) return true; const cp = Array.isArray(m) ? m : cpOf(m); return cp.includes(c); }
  function whoDecides(m) { const cp = Array.isArray(m) ? m : cpOf(m); return cp.map(c => CP_L[c]).join(' / '); }
  // Financements selon la collectivité : les départements et régions n’ont plus de taxe foncière
  function finLabel(lev, fin) { const f = (FIN[lev && lev.lvl] || FIN.local).find(z => z.id === fin); if (!f) return ''; if (fin === 'taxe' && lev && lev.scale === 'dep') return 'Hausse des droits de mutation (frais de notaire)'; if (fin === 'taxe' && lev && lev.scale === 'reg') return 'Hausse de la taxe sur les cartes grises'; if (fin === 'subventions' && lev && lev.scale === 'ue') return 'Ressources propres européennes'; if (lev && lev.scale === 'nat') return { redeploiement: 'Économies sur d’autres dépenses de l’État', taxe: 'Hausse d’un impôt national', emprunt: 'Déficit et dette de l’État', subventions: 'Redéploiement de crédits européens' }[fin] || f.l; return f.l; }
  const SCALE = { dep: { f: 1.6e9, i: 0.35e9 }, reg: { f: 2.6e9, i: 1.3e9 }, ue: { f: 190e9, i: 60e9 }, nat: { f: 100e9, i: 33e9 } };

