  function leversFor(lvl, th, pop, t) { const c = t ? TYPE_CP[t] : (lvl === 'local' ? 'com' : 'etat'); const free = ['dep', 'reg', 'sen', 'ue'].includes(c);
    return LEVERS.filter(l => (free || l.lvl === lvl) && (!th || l.th === th) && (!c || l.cp.includes(c)) && (c !== 'com' || fits(l, pop))); }
