  function bestFin(lev, v, com) { return FIN[lev.lvl].filter(f => f.id !== 'aucun').map(f => ({ f: f.id, c: evaluate(lev, v, f.id, com).cred })).sort((a, b) => b.c - a.c)[0].f; }
  return { NAT, local, LEVERS, FIN, PROBLEMS, evaluate, ltpl, fits, leversFor, problemsFor, themesFor, bestFin, cpOf, inComp, whoDecides, finLabel, TYPE_CP, CP_L, SCALE };
